     * m21.
     */
    public var c: Double
    /**
     * m22.
     */
    public var d: Double
    /**
     * Translation x.
     */
    public var tx: Double
    /**
     * Translation y.
     */
    public var ty: Double

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * m11.
         */a: Double, 
        /**
         * m12.
         */b: Double, 
        /**
         * m21.
         */c: Double, 
        /**
         * m22.
         */d: Double, 
        /**
         * Translation x.
         */tx: Double, 
        /**
         * Translation y.
         */ty: Double) {
        self.a = a
        self.b = b
        self.c = c
        self.d = d
        self.tx = tx
        self.ty = ty
    }

    

    
}

