/**
 * Why an engine call failed. Swift sees this as `EngineError` (an `Error` with associated values).
 */
public 
enum EngineError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A JSON argument could not be parsed (design, transaction, options).
     */
    case InvalidJson(
        /**
         * Parser message.
         */detail: String
    )
    /**
     * No design is loaded (call `load` first).
     */
    case NoDesign
    /**
     * The design has no page with this id (or no pages at all).
     */
    case PageNotFound(
        /**
         * Requested page id.
         */id: String
    )
    /**
     * No node with this id.
     */
    case NodeNotFound(
        /**
         * Requested node id.
         */id: String
    )
    /**
     * The node exists but is not a text node.
     */
    case NotText(
        /**
         * Node id.
         */id: String
    )
    /**
     * An argument is out of range (viewport size, scale, buffer too small, color syntax).
     */
    case InvalidArgument(
        /**
         * What is wrong.
         */detail: String
    )
    /**
     * Rendering or exporting failed.
     */
    case Render(
        /**
         * Renderer message.
         */detail: String
    )
    /**
     * Font bytes could not be registered.
     */
    case Font(
        /**
         * Font database message.
         */detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension EngineError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEngineError: FfiConverterRustBuffer {
    typealias SwiftType = EngineError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EngineError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidJson(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NoDesign
        case 3: return .PageNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 4: return .NodeNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotText(
            id: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidArgument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Render(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Font(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EngineError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidJson(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .NoDesign:
            writeInt(&buf, Int32(2))
        
        
        case let .PageNotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .NodeNotFound(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .NotText(id):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .InvalidArgument(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Render(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Font(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


