/**
 * Caret movements.
 */

public enum TextMovement: Equatable, Hashable {
    
    /**
     * One grapheme towards the left edge (bidi-aware).
     */
    case left
    /**
     * One grapheme towards the right edge (bidi-aware).
     */
    case right
    /**
     * One line up (keeps `x`).
     */
    case up
    /**
     * One line down (keeps `x`).
     */
    case down
    /**
     * Next grapheme in logical order.
     */
    case graphemeForward
    /**
     * Previous grapheme in logical order.
     */
    case graphemeBackward
    /**
     * Next word boundary.
     */
    case wordForward
    /**
     * Previous word boundary.
     */
    case wordBackward
    /**
     * Start of the visual line.
     */
    case lineStart
    /**
     * End of the visual line.
     */
    case lineEnd
    /**
     * Start of the paragraph.
     */
    case paragraphStart
    /**
     * End of the paragraph.
     */
    case paragraphEnd





}

